const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Fire location: El Escondido area, Ensenada, Baja California
  const firePoint = ee.Geometry.Point([-116.6, 31.8]);

  // Define 100km westward extent over Pacific Ocean
  const westernPoint = ee.Geometry.Point([-117.5, 31.8]); // ~100km west
  const searchArea = ee.Geometry.Rectangle([-117.5, 31.5, -116.0, 32.1]);

  // Date range around Jan 23, 2025
  const targetDate = '2025-01-23';
  const startDate = '2025-01-22';
  const endDate = '2025-01-24';

  console.log('Searching for smoke plume data near', targetDate);

  // Try Sentinel-5P Aerosol Index (best for smoke detection)
  let s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterBounds(searchArea)
    .filterDate(startDate, endDate)
    .select('absorbing_aerosol_index');

  const s5pCount = s5p.size().getInfo();
  console.log('Sentinel-5P images found:', s5pCount);

  if (s5pCount === 0) {
    // Fallback to Sentinel-2 for visual smoke detection
    let s2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(searchArea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

    const s2Count = s2.size().getInfo();
    console.log('Sentinel-2 images found:', s2Count);

    if (s2Count === 0) {
      console.log('No satellite data available for the specified date and location.');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use Sentinel-2 - analyze aerosol/smoke via band ratios
    const img = s2.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    const date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm').getInfo();
    console.log('Using Sentinel-2 image from:', date);

    // Check for elevated aerosol signal westward
    const aerosolProxy = img.select('B1').divide(img.select('B4')); // Aerosol/Coastal band ratio

    // Sample along westward transect
    const transect = ee.Geometry.LineString([[-116.6, 31.8], [-117.5, 31.8]]);
    const samples = aerosolProxy.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: transect.buffer(5000),
      scale: 1000,
      maxPixels: 1e9
    });

    const aerosolValue = samples.get('B1').getInfo();

    if (aerosolValue === null || aerosolValue === undefined) {
      console.log('No valid pixels in transect area.');
      console.log('<answer>C2</answer>');
      return;
    }

    console.log('Aerosol proxy value along 100km transect:', aerosolValue.toFixed(3));

    // Baseline comparison - check if aerosol elevated
    if (aerosolValue > 1.2) {
      console.log('Elevated aerosol signal detected extending westward >100km');
      console.log('<answer>A</answer>');
    } else {
      console.log('No significant smoke plume extending >100km westward');
      console.log('<answer>B</answer>');
    }

  } else {
    // Use Sentinel-5P Aerosol Index
    const img = s5p.first();
    const date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm').getInfo();
    console.log('Using Sentinel-5P image from:', date);

    // Check aerosol index along westward transect
    const transect = ee.Geometry.LineString([[-116.6, 31.8], [-117.5, 31.8]]);
    const stats = img.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: transect.buffer(5000),
      scale: 3000,
      maxPixels: 1e9
    });

    const aiMean = stats.get('absorbing_aerosol_index_mean').getInfo();
    const pixelCount = stats.get('absorbing_aerosol_index_count').getInfo();

    if (pixelCount === 0) {
      console.log('No valid pixels in analysis area.');
      console.log('<answer>C2</answer>');
      return;
    }

    console.log('Aerosol Index mean along 100km transect:', aiMean.toFixed(2));
    console.log('Valid pixels:', pixelCount);

    // Aerosol Index > 1 typically indicates absorbing aerosols (smoke/dust)
    if (aiMean > 1.0) {
      console.log('Significant smoke plume detected extending >100km westward');
      console.log('<answer>A</answer>');
    } else {
      console.log('No significant smoke plume extending >100km westward');
      console.log('<answer>B</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
